<script>import {dollars} from '$lib/format.js';export let data;</script>
<div class="heading"><div><p class="eyebrow">Your overview</p><h1>Good to see you, {data.user.name.split(' ')[0]}.</h1><p class="muted">Keep your groups moving and your balances clear.</p></div><div class="heading-actions"><a class="button secondary" href="/groups/join">Join group</a><a class="button" href="/groups/new">+ New group</a></div></div>
<section class="grid"><div class="card"><div class="title"><h2>Your groups</h2><a href="/groups/new">Create one</a></div>{#if data.groups.length}{#each data.groups as group}<a class="group" href={'/groups/'+group.id}><span class="avatar">{group.name[0].toUpperCase()}</span><span><b>{group.name}</b><small>{group.memberCount} member{group.memberCount===1?'':'s'}</small></span><span>→</span></a>{/each}{:else}<div class="empty"><p>You haven't joined a group yet.</p><a class="button secondary" href="/groups/join">Join a group</a></div>{/if}</div><div class="card"><div class="title"><h2>Recent expenses</h2></div>{#if data.expenses.length}{#each data.expenses as e}<div class="expense"><span><b>{e.description}</b><small>{e.groupName} · {e.date}</small></span><strong>{dollars(e.amount)}</strong></div>{/each}{:else}<div class="empty"><p>Your recent expenses will appear here.</p></div>{/if}</div></section>
<style>.heading{align-items:end;display:flex;justify-content:space-between;margin:2rem 0}.heading-actions{display:flex;gap:.6rem}.eyebrow{color:#d26d35;font-size:.8rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase}h1{font-size:clamp(2rem,5vw,3.3rem);margin:.3rem 0}.muted,small{color:#58746b}.grid{display:grid;gap:1.25rem;grid-template-columns:1fr 1fr}.title{align-items:center;display:flex;justify-content:space-between}.title h2{font-size:1.2rem}.title a{color:#146c52;font-weight:700}.group,.expense{align-items:center;border-top:1px solid #e6efeb;display:flex;gap:.75rem;padding:.85rem 0;text-decoration:none}.group>span:nth-child(2),.expense>span:first-child{display:grid;gap:.2rem;flex:1}.avatar{align-items:center;background:#d6f2e4;border-radius:10px;color:#146c52;display:flex;font-weight:800;height:2.5rem;justify-content:center;width:2.5rem}.expense strong{color:#146c52}.empty{color:#58746b;padding:1.5rem 0;text-align:center}@media(max-width:700px){.heading{align-items:flex-start;flex-direction:column;gap:1rem}.grid{grid-template-columns:1fr}.heading-actions{flex-wrap:wrap}}</style>
